def count_arrangement(n):
    used = [False] * (n + 1)
    count = 0

    def backtrack(pos):
        nonlocal count
        if pos > n:
            count += 1
            return
        for num in range(1, n + 1):
            if used[num]:
                continue
            if num % pos == 0 or pos % num == 0:
                used[num] = True
                backtrack(pos + 1)
                used[num] = False

    backtrack(1)
    return count

